SELECT dr.*, d.device_name, d.device_no, u.real_name AS user_name FROM device_reservation dr LEFT JOIN device d ON dr.device_id = d.id LEFT JOIN `user` u ON dr.user_id = u.id
AND dr.status = #{status} AND dr.user_id = #{userId}
ORDER BY dr.create_time DESC

SELECT COUNT(*) FROM device_reservation
WHERE device_id = #{deviceId} AND reserve_date = #{reserveDate}
AND time_slot = #{timeSlot} AND status IN (0, 1)
AND id != #{excludeId}

mapper.update:
UPDATE device_reservation
status = #{status}, audit_user_id = #{auditUserId}, audit_time = #{auditTime},
WHERE id = #{id}
